// Package notices carries the open-source licence notices of everything
// linked into Olsyn Drive (Go modules and the desktop page's npm packages),
// and the attribution WinFsp's licence asks for. NOTICE.txt is generated by
// internal/notices/gen ("make notices"); do not edit it by hand.
package notices

import _ "embed"

//go:embed NOTICE.txt
var text string

// Text is the full notice: attributions, then each component's licence.
func Text() string { return text }
